import{_ as t,o as r,c as s,l as o,t as n,N as a}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"du | x-cmd man (man1) | estimate file space usage","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | du - estimate file space usage","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"du | x-cmd man (man1) | estimate file space usage"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | du - estimate file space usage"}]]},"headers":[],"params":{"isMan":true,"man":"du","category":"man1","desc":"estimate file space usage"},"relativePath":"man1/du.md","filePath":"man1/du.md"}'),d={name:"man1/du.md"},i={class:"visually-hidden"},l=a('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>du - estimate file space usage</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>du</strong> [<em>OPTION</em>]... [<em>FILE</em>]... <br> <strong>du</strong> [<em>OPTION</em>]... <em>--files0-from=F</em></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Summarize device usage of the set of FILEs, recursively for directories.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-0</strong>, <strong>--null</strong></dt><dd>end each output line with NUL, not newline</dd><dt><strong>-a</strong>, <strong>--all</strong></dt><dd>write counts for all files, not just directories</dd><dt><strong>--apparent-size</strong></dt><dd>print apparent sizes rather than device usage; although the apparent size is usually smaller, it may be larger due to holes in (&#39;sparse&#39;) files, internal fragmentation, indirect blocks, and the like</dd><dt><strong>-B</strong>, <strong>--block-size</strong>=<em>SIZE</em></dt><dd>scale sizes by SIZE before printing them; e.g., &#39;-BM&#39; prints sizes in units of 1,048,576 bytes; see SIZE format below</dd><dt><strong>-b</strong>, <strong>--bytes</strong></dt><dd>equivalent to &#39;--apparent-size <strong>--block-size</strong>=<em>1</em>&#39;</dd><dt><strong>-c</strong>, <strong>--total</strong></dt><dd>produce a grand total</dd><dt><strong>-D</strong>, <strong>--dereference-args</strong></dt><dd>dereference only symlinks that are listed on the command line</dd><dt><strong>-d</strong>, <strong>--max-depth</strong>=<em>N</em></dt><dd>print the total for a directory (or file, with <strong>--all</strong>) only if it is N or fewer levels below the command line argument; <strong>--max-depth</strong>=<em>0</em> is the same as <strong>--summarize</strong></dd><dt><strong>--files0-from</strong>=<em>F</em></dt><dd>summarize device usage of the NUL-terminated file names specified in file F; if F is -, then read names from standard input</dd><dt><strong>-H</strong></dt><dd>equivalent to <strong>--dereference-args</strong> (<strong>-D</strong>)</dd><dt><strong>-h</strong>, <strong>--human-readable</strong></dt><dd>print sizes in human readable format (e.g., 1K 234M 2G)</dd><dt><strong>--inodes</strong></dt><dd>list inode usage information instead of block usage</dd><dt><strong>-k</strong></dt><dd>like <strong>--block-size</strong>=<em>1K</em></dd><dt><strong>-L</strong>, <strong>--dereference</strong></dt><dd>dereference all symbolic links</dd><dt><strong>-l</strong>, <strong>--count-links</strong></dt><dd>count sizes many times if hard linked</dd><dt><strong>-m</strong></dt><dd>like <strong>--block-size</strong>=<em>1M</em></dd><dt><strong>-P</strong>, <strong>--no-dereference</strong></dt><dd>don&#39;t follow any symbolic links (this is the default)</dd><dt><strong>-S</strong>, <strong>--separate-dirs</strong></dt><dd>for directories do not include size of subdirectories</dd><dt><strong>--si</strong></dt><dd>like <strong>-h</strong>, but use powers of 1000 not 1024</dd><dt><strong>-s</strong>, <strong>--summarize</strong></dt><dd>display only a total for each argument</dd><dt><strong>-t</strong>, <strong>--threshold</strong>=<em>SIZE</em></dt><dd>exclude entries smaller than SIZE if positive, or entries greater than SIZE if negative</dd><dt><strong>--time</strong></dt><dd>show time of the last modification of any file in the directory, or any of its subdirectories</dd><dt><strong>--time</strong>=<em>WORD</em></dt><dd>show time as WORD instead of modification time: atime, access, use, ctime or status</dd><dt><strong>--time-style</strong>=<em>STYLE</em></dt><dd>show times using STYLE, which can be: full-iso, long-iso, iso, or +FORMAT; FORMAT is interpreted like in &#39;date&#39;</dd><dt><strong>-X</strong>, <strong>--exclude-from</strong>=<em>FILE</em></dt><dd>exclude files that match any pattern in FILE</dd><dt><strong>--exclude</strong>=<em>PATTERN</em></dt><dd>exclude files that match PATTERN</dd><dt><strong>-x</strong>, <strong>--one-file-system</strong></dt><dd>skip directories on different file systems</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>Display values are in units of the first available SIZE from <strong>--block-size</strong>, and the DU_BLOCK_SIZE, BLOCK_SIZE and BLOCKSIZE environment variables. Otherwise, units default to 1024 bytes (or 512 if POSIXLY_CORRECT is set).</p><p>The SIZE argument is an integer and optional unit (example: 10K is 10*1024). Units are K,M,G,T,P,E,Z,Y,R,Q (powers of 1024) or KB,MB,... (powers of 1000). Binary prefixes can be used, too: KiB=K, MiB=M, and so on.</p><h2 id="patterns" tabindex="-1">PATTERNS <a class="header-anchor" href="#patterns" aria-label="Permalink to &quot;PATTERNS&quot;">​</a></h2><p>PATTERN is a shell pattern (not a regular expression). The pattern <strong>?</strong> matches any one character, whereas *<em>*</em> * matches any string (composed of zero, one or multiple characters). For example, <strong>*.o</strong> will match any files whose names end in <strong>.o</strong>. Therefore, the command</p><blockquote><p><strong>du --exclude=&#39;*.o&#39;</strong></p></blockquote><p>will skip all files and subdirectories ending in <strong>.o</strong> (including the file <strong>.o</strong> itself).</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Torbjorn Granlund, David MacKenzie, Paul Eggert, and Jim Meyering.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/du%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/du\\</a>&gt; <br> or available locally via: info &#39;(coreutils) du invocation&#39;</p>',22);function g(e,m,c,h,u,p){return r(),s("div",null,[o("h1",i,n(e.$params.man),1),l])}const y=t(d,[["render",g]]);export{b as __pageData,y as default};
